def link_from_past_purchases(apps, schema_editor):
    """
    Every product already bought from a supplier becomes a supplier
    product, with the price and date of the latest bill. Only adds rows.
    """

    PurchaseItem = apps.get_model("pharma_app", "PurchaseItem")
    SupplierProduct = apps.get_model("pharma_app", "SupplierProduct")

    latest = {}
    items = (
        PurchaseItem.objects
        .select_related("purchase")
        .order_by("purchase__bill_date", "id")
    )
    for item in items.iterator():
        purchase = item.purchase
        latest[(purchase.supplier_id, item.product_id)] = (
            purchase.retailer_id, item.purchase_price, purchase.bill_date,
        )

    SupplierProduct.objects.bulk_create(
        [
            SupplierProduct(
                retailer_id=retailer_id, supplier_id=supplier_id, product_id=product_id,
                last_purchase_price=price, last_purchase_date=bill_date,
            )
            for (supplier_id, product_id), (retailer_id, price, bill_date) in latest.items()
        ],
        ignore_conflicts=True,
    )

